WITH unpacked AS (SELECT id, items, ship_to, attributes, ARRAY_MAX(TRANSFORM(items, item -> item.price)) AS max_item_price, ARRAY_CONTAINS(coupon_codes, 'VIP') AS used_vip, ARRAY_JOIN(ARRAY_SORT(coupon_codes), ',') AS coupons_text, attributes['gift'] AS gift FROM carts) SELECT CASE WHEN max_item_price >= 262 THEN 'HIGH' ELSE 'LOW' END AS max_item_price_tier, PERCENTILE_APPROX(max_item_price, 0.5) AS max_item_price_p50, PERCENTILE_APPROX(max_item_price, 0.9) AS max_item_price_p90, APPROX_PERCENTILE(max_item_price, ARRAY(0.25, 0.5, 0.75)) AS max_item_price_quartiles, ROUND(AVG(max_item_price), 2) AS avg_max_item_price, APPROX_PERCENTILE(max_item_price, ARRAY(0.25, 0.5, 0.75)) AS max_item_price_quartiles_2 FROM unpacked GROUP BY CASE WHEN max_item_price >= 262 THEN 'HIGH' ELSE 'LOW' END HAVING avg_max_item_price > 0;
